async function bytesFor(id){const r=await native('read',{id});try{const res=await fetch(r.url,{cache:'no-store'});if(!res.ok)throw new Error('문서 데이터를 읽지 못했어요.');return {...r,bytes:await res.arrayBuffer()};}finally{await native('release',{token:r.token});}}
