 if(a==='folder-enter')return enterFolder(b.dataset.path);if(a==='folder-up')return enterFolder(state.folder.path.slice(0,state.folder.path.lastIndexOf('/')));
 if(a==='volume'){const f=state.folder;$('#folder-list').innerHTML=state.volumes.map(v=>btn('folder-enter',icon('hard-drive')+`<span class="folder-row-name">${esc(v.name)}</span>`,'folder-row',`data-path="${esc(v.path)}"`)).join('');icons();return;}
 if(a==='folder-search'){const f=state.folder;f.search=!f.search;folderRender();return;}if(a==='folder-clear'){state.folder.term='';$('#folder-query').value='';folderRows();return;}
